function renderSuspensions(){
 if(view!=='club')return;const host=$('suspensions-panel');if(!host)return;const model=Suspensions.read(season),esc=escapeText,open=host.querySelector('details')?.open||false,names={league:'리그',cup:'국내컵',europe:'유럽 대회'};
 const rows=model.rows.slice().sort((a,b)=>Number(b.blocked)-Number(a.blocked)||b.pending-a.pending||b.yellows-a.yellows||a.id.localeCompare(b.id));
 host.innerHTML=`<section class="suspensions-card" aria-labelledby="suspensions-title"><header><h2 id="suspensions-title">경고와 출전 정지</h2><span>${model.enabled?'이번 경기 정지 '+model.blocked.length+'명':'기존 경기 규칙 유지'}</span></header>${model.enabled?`<p>같은 대회 경고 3회 또는 퇴장 → 1경기 정지${model.deferred.length?' · 인원 부족으로 '+model.deferred.length+'명 집행 연기':''}</p><details${open?' open':''}><summary>대회별 선수 기록과 규칙</summary>${rows.length?'<ul>'+rows.map(p=>`<li><strong>${esc(p.name)} · ${p.pos}</strong><span>${names[p.competition]} · 경고 ${p.yellows}/3${p.pending?' · 정지 '+p.pending+'경기':''}</span><small>${p.blocked?'이번 경기 출전 불가':p.deferred?'포지션 인원 부족 · 다음 같은 대회 경기로 집행 연기':p.pending?'다음 해당 대회 경기에서 집행':p.yellows===2?'경고 한 번 더 받으면 정지':'누적 기록'}${p.pending?' · '+esc(p.reason):''}</small></li>`).join('')+'</ul>':'<p>아직 누적 경고나 출전 정지가 없습니다.</p>'}<p>확정된 경기만 집계합니다. 리그·국내컵·유럽 대회는 따로 집계하며, 다른 대회를 뛰어도 정지는 줄지 않습니다. 퇴장 경기의 경고는 누적에 중복 합산하지 않습니다.</p><p>18명 선수단에서 부상과 정지가 겹쳐 필수 포지션 인원이 부족하면 일부 정지를 연기합니다. 부상으로 쉬어도 정지는 집행됩니다. 새 시즌에는 경고와 남은 정지를 초기화합니다.</p></details>`:`<p>기존 저장의 과거 경고는 소급 적용하지 않습니다. 켜면 지금 준비 중인 경기부터 누적 경고와 다음 경기 정지를 적용합니다.</p><button type="button" class="secondary" id="enable-suspensions"${model.canEnable?'':' disabled'}>누적 경고·출전 정지 적용하기</button><small>카드가 있는 새 경기 준비에서 팀 대화 전에 적용할 수 있습니다.</small>`}</section>`;
 const button=$('enable-suspensions');if(button)button.onclick=()=>{if(button.disabled)return;button.disabled=true;action(()=>{season=Suspensions.enable(season);state=season.match;selected=null;});};
}
